styles:
.page-case .case-hero { padding-top: clamp(140px, 18vh, 220px); padding-bottom: clamp(24px, 4vw, 48px); }
.page-case .case-hero__tags { display: flex; flex-wrap: wrap; gap: 10px; margin-bottom: clamp(20px, 3vw, 34px); }
.page-case .case-hero__tags span {
  font-size: clamp(13px, 1vw, 15px); color: var(--red);
  border: 1px solid var(--line); border-radius: 999px; padding: 7px 16px;
}
.page-case .case-hero__title { font-size: clamp(44px, 8vw, 118px); line-height: 1.04; letter-spacing: -0.01em; max-width: 16ch; }
.page-case .case-hero__meta {
  display: flex; flex-wrap: wrap; gap: 10px 28px; margin-top: clamp(22px, 3vw, 38px);
  font-family: var(--font-display); font-size: clamp(16px, 1.3vw, 20px); color: var(--grey-700);
}
.page-case .case-hero__meta span { display: inline-flex; align-items: center; gap: 12px; }
.page-case .case-hero__meta span::before { content: ""; width: 7px; height: 7px; border-radius: 50%; background: var(--red); }
.page-case .case-hero__lead { margin-top: clamp(26px, 3.4vw, 44px); max-width: 62ch; font-size: clamp(18px, 1.5vw, 24px); color: var(--grey-700); }

.page-case .case-cover { border-radius: var(--radius-lg); overflow: hidden; background: var(--bg-alt); }
.page-case .case-cover img { width: 100%; height: clamp(260px, 46vw, 720px); object-fit: cover; }

.page-case .case-body { display: grid; grid-template-columns: 1fr 1fr; gap: clamp(28px, 5vw, 90px); }
.page-case .case-block { padding-block: clamp(30px, 3.6vw, 56px); border-bottom: 1px solid var(--line); }
.page-case .case-block:first-of-type { border-top: 1px solid var(--line); }
.page-case .case-block h2 {
  font-size: clamp(28px, 3.4vw, 52px); line-height: 1.02; color: var(--red);
}
.page-case .case-block__body p { color: var(--grey-700); font-size: clamp(16px, 1.15vw, 19px); margin-bottom: 16px; }
.page-case .case-block__body p:last-child { margin-bottom: 0; }
.page-case .case-list { display: flex; flex-direction: column; gap: 18px; }
.page-case .case-list li { position: relative; padding-left: 40px; color: var(--grey-700); font-size: clamp(16px, 1.15vw, 19px); }
.page-case .case-list li .n {
  position: absolute; left: 0; top: 0; font-family: var(--font-display); color: var(--red);
  font-size: clamp(16px, 1.15vw, 19px); font-weight: 600;
}
.page-case .case-list li strong { color: var(--grey-900); font-weight: 400; }

.page-case .case-gallery { display: grid; grid-template-columns: 1fr 1fr; gap: clamp(16px, 2vw, 28px); }
.page-case .case-gallery figure { border-radius: var(--radius); overflow: hidden; background: var(--bg-alt); }
.page-case .case-gallery img { width: 100%; height: clamp(220px, 30vw, 460px); object-fit: cover; transition: transform .8s var(--ease); }
.page-case .case-gallery figure:hover img { transform: scale(1.03); }

.page-case .case-nav {
  display: flex; justify-content: space-between; align-items: center; gap: 20px; flex-wrap: wrap;
  padding-top: clamp(30px, 4vw, 60px); border-top: 1px solid var(--line);
}
.page-case .case-nav__prevnext { display: flex; gap: 26px; flex-wrap: wrap; }
.page-case .case-nav__prevnext a { color: var(--grey-500); font-family: var(--font-display); transition: color .25s var(--ease); }
.page-case .case-nav__prevnext a:hover { color: var(--red); }
.page-case .case-viewall {
  display: inline-flex; align-items: center; gap: 12px; font-family: var(--font-display);
  font-size: clamp(18px, 1.5vw, 24px); color: var(--grey-900); transition: color .25s var(--ease);
}
.page-case .case-viewall:hover { color: var(--red); }
.page-case .case-viewall .arrow {
  width: 40px; height: 40px; border-radius: 50%; border: 1.5px solid var(--red); color: var(--red);
  display: grid; place-items: center; transition: background .3s var(--ease), color .3s var(--ease), transform .3s var(--ease);
}
.page-case .case-viewall:hover .arrow { background: var(--red); color: #fff; transform: translateX(2px); }

@media (max-width: 860px) {
  .page-case .case-body { grid-template-columns: 1fr; gap: 0; }
  .page-case .case-gallery { grid-template-columns: 1fr; }
}
